        """
        :type initial: str
        :type target: str
        :rtype: int
        """
        if len(initial) < len(target):
            initial, target = target, initial
        result = 0
        dp = [0]*(len(target)+1)
        for i in xrange(len(initial)):
            for j in reversed(xrange(len(target))):
