    def __init__(self, len=0, val="", left=None, right=None):
        pass


# binary search tree
class Solution(object):
    def getKthCharacter(self, root, k):
        """
        :type root: Optional[RopeTreeNode]
        :type k: int
        :rtype: str
        """
        while root.len:
            l = max(root.left.len, len(root.left.val)) if root.left else 0
            if k <= l:
